/*
 * EML-HeadlessBOT - own code only. The Minecraft client jar stays outside this artifact.
 *
 *   compile time   against libs/minecraft-<version>-open.jar: the client jar with access flags widened and
 *                  method bodies dropped. Generated by the `generateOpenJar` task below, never executed.
 *   runtime        the untouched official jar, fetched into versions/ by the bot on first run.
 *
 * WHY THE GENERATED JAR NEEDS NO SPECIAL HANDLING HERE
 *
 * `generateOpenJar` declares its output, and `compileJava` depends on it, so the file exists before javac
 * reads its classpath. There is no pre-existing file to ship and no dependency to resolve out of a
 * repository: a clean checkout builds with `gradlew build` and nothing else on disk.
 *
 * No fat-jar plugin is used on purpose. The runtime classpath already contains exactly what should be
 * packaged (the `implementation` dependencies), because everything the client provides at runtime is
 * declared `compileOnly`. Packing it by hand is a dozen lines and one less third-party plugin to keep
 * compatible with Gradle and the JDK.
 */

plugins {
    java
    // JitPack builds this repository and expects a publishToMavenLocal task to exist; without a
    // publication it stops with "No build artifacts found" even when compilation succeeded.
    `maven-publish`
}

// JitPack passes the coordinate it will look for as project properties (-Pgroup / -Pversion). Those have to
// win over the defaults, otherwise the artifact is published under a name JitPack never reads.
group = providers.gradleProperty("group").getOrElse("com.mcbot")
version = providers.gradleProperty("version").getOrElse("1.2.0-26.1.2")

val mcVersion = "26.1.2"

/** The official client jar the generator reads; downloaded by the generator itself when missing. */
val vanillaJar = layout.projectDirectory.file("versions/$mcVersion/$mcVersion.jar")

/** The generated compile-only view. Git-ignored, reproducible, never packaged. */
val openJar = layout.projectDirectory.file("libs/minecraft-$mcVersion-open.jar")

/** -Popenjar.force=true regenerates even when the existing output is up to date. */
val forceOpenJar = providers.gradleProperty("openjar.force").getOrElse("false")

repositories {
    // Official hosts only. A domestic mirror resolves faster locally, but the same build runs on JitPack,
    // whose machines sit outside China: there the mirrors are slower than the hosts they mirror.
    mavenCentral()

    // The client's own libraries (com.mojang:logging, :blocklist) are published here and nowhere else, so
    // this one is restricted to that group: every other artifact skips it instead of 404-ing against it.
    maven {
        name = "minecraft"
        url = uri("https://libraries.minecraft.net/")
        content {
            includeGroupByRegex("com\\.mojang.*")
        }
    }
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

tasks.withType<JavaCompile>().configureEach {
    options.release = 25
    options.encoding = "UTF-8"
}

// ---------------------------------------------------------------------------------------------
// Generator source set
//
// The generator lives in the main tree (it is also compiled into the bot, where the bootstrap reuses
// the same downloader). Giving it its own source set lets Gradle compile exactly those files with
// their own classpath, without copying them anywhere.
// ---------------------------------------------------------------------------------------------

val generator = sourceSets.create("generator") {
    java.srcDir("src/main/java")
}

tasks.named<JavaCompile>(generator.compileJavaTaskName) {
    include(
        "eml/engine/OpenJarTool.java",
        "eml/bootstrap/MojangRuntime.java",
        "eml/util/LaunchLog.java"
    )
}

dependencies {
    // ---- packaged into the output jar ----
    implementation("org.ow2.asm:asm:9.9")
    implementation("org.ow2.asm:asm-tree:9.9")
    implementation("org.ow2.asm:asm-commons:9.9")
    implementation("org.jline:jline:3.30.16")
    implementation("org.fusesource.jansi:jansi:2.4.3")
    implementation("org.yaml:snakeyaml:2.5")
    implementation("com.google.code.gson:gson:2.13.2")

    // ---- supplied by the client or the launcher at runtime ----
    compileOnly("com.mojang:authlib:7.0.63")
    compileOnly("com.mojang:brigadier:1.3.10")
    compileOnly("com.mojang:datafixerupper:9.0.19")
    compileOnly("com.mojang:logging:1.6.11")
    compileOnly("com.mojang:blocklist:1.0.10")
    compileOnly("io.netty:netty-all:4.2.7.Final")
    compileOnly("com.google.guava:guava:33.5.0-jre")
    compileOnly("it.unimi.dsi:fastutil:8.5.18")
    compileOnly("org.apache.commons:commons-lang3:3.19.0")
    compileOnly("org.apache.commons:commons-compress:1.28.0")
    compileOnly("commons-io:commons-io:2.20.0")
    compileOnly("commons-codec:commons-codec:1.19.0")
    compileOnly("net.sf.jopt-simple:jopt-simple:5.0.4")
    compileOnly("com.ibm.icu:icu4j:77.1")
    compileOnly("org.joml:joml:1.10.8")
    compileOnly("org.slf4j:slf4j-api:2.0.17")
    compileOnly("org.apache.logging.log4j:log4j-api:2.25.2")
    compileOnly("org.apache.logging.log4j:log4j-core:2.25.2")
    compileOnly("org.apache.logging.log4j:log4j-slf4j2-impl:2.25.2")
    compileOnly("org.jspecify:jspecify:1.0.0")
    compileOnly("org.jetbrains:annotations:24.1.0")

    // ---- the generated view of the client ----
    // A file dependency: it is added to javac's classpath and nothing else. Not in runtimeClasspath,
    // so it can never end up inside the jar.
    compileOnly(files(openJar))

    // ---- the generator's own classpath ----
    "generatorImplementation"("org.ow2.asm:asm:9.9")
    "generatorImplementation"("org.ow2.asm:asm-tree:9.9")
    "generatorImplementation"("com.google.code.gson:gson:2.13.2")
}

// ---------------------------------------------------------------------------------------------
// Generated compile view
// ---------------------------------------------------------------------------------------------

val generateOpenJar = tasks.register<JavaExec>("generateOpenJar") {
    group = "build"
    description = "Generates libs/minecraft-$mcVersion-open.jar, the compile-only access-opened client view."

    dependsOn(tasks.named(generator.classesTaskName))

    val out = openJar.asFile
    outputs.file(out)
    // Re-run when the generator's own sources change, and whenever the version or the force flag does.
    inputs.files(generator.output)
    inputs.property("mcVersion", mcVersion)
    inputs.property("force", forceOpenJar)
    // The client jar is deliberately NOT an input: the generator downloads it when it is missing, so
    // declaring it here would make the task unrunnable on a clean checkout.

    // JavaExec rather than Exec: the classpath is a live FileCollection that Gradle resolves when the
    // task runs (so a cold start still does not resolve configurations at configuration time), while the
    // command line stays declarative. An Exec task has to build its own argv in a doFirst closure, and
    // that closure captures the script object, which the configuration cache cannot store - the whole
    // build then fails at cache-store time with "cannot serialize Gradle script object references".
    classpath = generator.runtimeClasspath
    mainClass.set("eml.engine.OpenJarTool")
    args = listOf(
        vanillaJar.asFile.path,
        out.path,
        projectDir.path,
        mcVersion,
        forceOpenJar
    )

    doFirst {
        // Only the declared output's parent; everything else is resolved by JavaExec itself.
        out.parentFile.mkdirs()
    }
}

tasks.named<JavaCompile>("compileJava") {
    // The open jar must exist before javac reads its classpath.
    dependsOn(generateOpenJar)
}

// ---------------------------------------------------------------------------------------------
// Output jar
// ---------------------------------------------------------------------------------------------

val runtimeLibs = configurations.runtimeClasspath

val fatJar = tasks.register<Jar>("fatJar") {
    group = "build"
    description = "Own classes plus the runtime libraries; the client jar is never packaged."

    archiveFileName = "EML-HeadlessBOT-$version.jar"

    manifest {
        attributes(
            "Main-Class" to "top.mcocet.hlbot.EML",
            "Premain-Class" to "eml.agent.EmlAgent",
            // Read by Telemetry so every report names the exact build it came from.
            "Implementation-Version" to version,
            "Can-Retransform-Classes" to "false",
            "Can-Initialize-On-Entry" to "false"
        )
    }

    from(sourceSets.main.get().output)

    // runtimeClasspath holds only `implementation` dependencies, which is exactly the packaging set.
    from({
        runtimeLibs.get()
            .filter { it.name.endsWith(".jar") }
            .map { zipTree(it) }
    }) {
        exclude(
            "META-INF/*.SF", "META-INF/*.DSA", "META-INF/*.RSA", "META-INF/*.EC", "META-INF/SIG-*",
            "module-info.class", "META-INF/versions/*/module-info.class"
        )
    }

    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
}

// One jar, not two: the plain `jar` task would collide with the same file name.
tasks.named<Jar>("jar") {
    enabled = false
}

tasks.named("assemble") {
    dependsOn(fatJar)
}

// ---------------------------------------------------------------------------------------------
// Local publication
//
// Exists for JitPack, which runs `publishToMavenLocal` and then collects the artifact from the local Maven
// repository. Only the packaged jar is published: nothing here is meant for Maven Central, and the client
// jar is not part of the artifact in any case.
// ---------------------------------------------------------------------------------------------

publishing {
    publications {
        create<MavenPublication>("maven") {
            artifactId = "EML-HeadlessBOT"
            artifact(fatJar)
        }
    }
}
